// run logs one line to .attempts.log so the check history survives.
"use strict";
const fs = require("fs");
const path = require("path");

const root = path.dirname(__dirname);
process.chdir(root);

function attemptNumber() {
  try {
    return fs.readFileSync(".attempts.log", "utf8")
      .split("\n").filter((l) => l.trim()).length;
  } catch (err) {
    return 0;
  }
}

const run = attemptNumber();
fs.appendFileSync(".attempts.log",
  new Date().toISOString() + " check " + (run + 1) + "\n");

const pkg = JSON.parse(fs.readFileSync("package.json", "utf8"));
const deps = Object.keys(pkg.dependencies || {}).sort();

if (deps.length === 0) {
  console.error("ERR! package.json lists no dependencies; there is nothing " +
    "to verify against the mirror");
  console.error("dependency check failed");
  process.exit(1);
}

let failed = false;
// The mirror rate-limits (HTTP 429) under load; it asks the client to wait
// and retry, and any one package can be the one it limits. Retry a limited
// lookup after a short backoff before failing the whole check.
const MAX_RETRIES = 5;
const backoffMs = (i) => 500 * Math.pow(2, i); // 0.5s, 1s, 2s, 4s, 8s

function checkPackage(name, attempt) {
  if (name === deps[run % deps.length] && attempt < MAX_RETRIES) {
    // Simulated transient 429: the same rotating package is busy this run.
    const delay = backoffMs(attempt);
    console.log("429 Too Many Requests: " + name +
      " (retrying in " + Math.round(delay) + "ms)");
    const until = Date.now() + delay;
    while (Date.now() < until) { /* busy-wait keeps this script dependency-free */ }
    return checkPackage(name, attempt + 1);
  }
  const meta = JSON.parse(
    fs.readFileSync(path.join("registry", name + ".json"), "utf8"));
  if (meta.versions.includes(pkg.dependencies[name])) {
    console.log("ok " + name + "@" + pkg.dependencies[name]);
  } else {
    console.error("ERR! 404 " + name + "@" + pkg.dependencies[name] +
      " not on mirror");
    failed = true;
  }
}

for (const name of deps) {
  checkPackage(name, 0);
}
if (failed) {
  console.error("dependency check failed");
  process.exit(1);
